using System;
using UnityEngine;
[Serializable] public class MapPoint { public float x, z; public Vector3 V(float y = 0) { return new Vector3(x,y,z); } }
[Serializable] public class MapRoad { public string id,name; public bool suppressPaint; public float width; public int sourceLanes,lanes,oneWay; public int DisplayLanes { get { return lanes>0?lanes:sourceLanes>=2?sourceLanes-sourceLanes%2:2; } } public MapPoint[] points; }
[Serializable] public class MapBuilding { public string id,name; public float height; public MapPoint[] points; public int[] triangles; }
[Serializable] public class MapLandmark : MapPoint { public string name,kind,status,evidence; }
[Serializable] public class MapArea { public string kind,name,evidence; public MapPoint[] points; public int[] triangles; }
[Serializable] public class MapTarget : MapPoint { public string name; public LeftTurnMode leftTurnMode; }
[Serializable] public class MapStop : MapPoint { public string name; public int laneEdge=-1; public float laneAt; public bool graphStop; public float dx,dz,width; public Vector3 Direction {get{return new Vector3(dx,0,dz);}} public Vector3 Passenger {get{return V(.16f)+TrafficSystem.Right(Direction)*(width*.5f+.85f);}} public bool CanStop(Vector3 p,Vector3 heading,float speed){var delta=p-Kerb;return speed<.56f && Vector3.Dot(heading,Direction)>.85f && Mathf.Abs(Vector3.Dot(delta,Direction))<4.5f && Mathf.Abs(Vector3.Dot(delta,TrafficSystem.Right(Direction)))<1.15f;} public Vector3 Kerb {get{return V()+TrafficSystem.Right(Direction)*(width*.5f-1.5f);}} }
[Serializable] public class HdEdge { public bool disabled; public string roadName,supplement; public string id,sourceId,fromNode,toNode,updated,evidence,status,ruleId; public int number,turn,change; public int[] next; public MapPoint[] points; public float sourceOffset; }
[Serializable] public class HybridApproach { public float dx,dz,width; }
[Serializable] public class HybridJunctionRule : MapPoint { public bool crosswalk,stopLine; public string facilityStatus="provisional",facilityEvidence="",facilityCheckedAt=""; public HybridApproach[] approaches=new HybridApproach[0]; public string id,status="provisional"; public bool allowLeft=true,allowRight=true,allowStraight=true; public int signalMode; public float dx,dz; }
[Serializable] public class HybridRoadOverride { public string roadId; public int lanes; }
[Serializable] public class HybridOverrides { public HybridJunctionRule[] junctions=new HybridJunctionRule[0]; public HybridRoadOverride[] roads=new HybridRoadOverride[0]; public string[] disabledPortals=new string[0]; }
[Serializable] public class HdTrialCase { public string name; public int turn,startEdge,goalEdge; public float startAt,goalAt; public int[] expected; public bool captureEnds; }
[Serializable] public class HdMark { public string id,type,kind; public MapPoint[] points; }
[Serializable] public class MapData { public bool supplementApplied; public string supplementSummary; public OsmCrossing[] osmCrossings; public string source,mapId,coordinateStatus; public float width,depth; public MapRoad[] roads; public MapBuilding[] buildings; public MapTarget[] targets; public MapStop[] stops; public MapLandmark[] landmarks; public MapArea[] areas; public HdEdge[] hdEdges; public HdTrialCase[] hdTrials; public HdMark[] hdMarks; public MapPoint[] hdSignals; public bool hybrid; public HybridJunctionRule[] junctionRules; public bool HasHd {get{return hdEdges!=null&&hdEdges.Length>0;}} }
